#!/usr/bin/env python3
import hashlib, html, json, runpy, time
from pathlib import Path
base=runpy.run_path(str(Path(__file__).with_name('publish_recipe_20260829_1000.py')),run_name='recipe_base')
TITLE='Almôndega Assada de Frango com Abobrinha para Bebê: Receita Macia'; SLUG_KEY='almondega-frango-abobrinha-bebe'; CLUSTER='Cluster 4 — Refeições com frango, carne e peixe'; KEYWORD='almôndega assada de frango com abobrinha para bebê'
MARKER=base['MARKER']; BLOG_ID=base['BLOG_ID']; COVER_DIR=base['COVER_DIR']; RAW_BASE=base['RAW_BASE']; LOG_PATH=base['LOG_PATH']; RESULT_PATH=base['RESULT_PATH']
def article(cover):
 schema={'@context':'https://schema.org','@type':'Recipe','name':TITLE,'image':[cover],'author':{'@type':'Organization','name':'Equipe Editorial do Receitas Para Pequenos'},'description':'Almôndegas assadas de frango com abobrinha, macias e úmidas, com formato adaptável às habilidades da criança.','recipeCategory':'Almoço e jantar','recipeCuisine':'Brasileira','keywords':KEYWORD+', alimentação complementar, frango, abobrinha','recipeYield':'8 a 10 almôndegas pequenas','recipeIngredient':['200 g de frango moído','1/2 abobrinha pequena ralada e levemente espremida','2 colheres (sopa) de aveia em flocos finos','1 colher (sopa) de cebola bem picada'],'recipeInstructions':[{'@type':'HowToStep','text':'Misture o frango moído, a abobrinha, a aveia e a cebola até formar uma massa úmida que mantenha o formato.'},{'@type':'HowToStep','text':'Modele porções pequenas sem compactar demais.'},{'@type':'HowToStep','text':'Asse em forno preaquecido a 200 °C até o frango estar completamente cozido no centro.'},{'@type':'HowToStep','text':'Espere amornar e adapte o formato às habilidades da criança antes de servir.'}]}
 sj=json.dumps(schema,ensure_ascii=False).replace('</','<\\/'); alt=html.escape(TITLE,quote=True)
 return f"""{MARKER}<div class='separator' style='clear:both;margin:0 0 24px;text-align:center'><img alt='{alt}' data-original-height='630' data-original-width='1200' src='{cover}' style='border-radius:14px;height:auto;max-width:100%;width:1200px'/></div><p><strong>Por Equipe Editorial do Receitas Para Pequenos</strong></p><p>Estas almôndegas assadas combinam frango e abobrinha em uma preparação macia para almoço ou jantar. A abobrinha ajuda a manter umidade na massa, enquanto a aveia dá estrutura sem deixar as porções excessivamente compactas.</p><p><strong>Atenção:</strong> adapte tamanho, formato e textura às habilidades da criança e ofereça sempre com ela sentada e supervisionada. Alergias, dificuldades de mastigação/deglutição e necessidades especiais exigem avaliação profissional individualizada.</p><h2>Ingredientes</h2><ul><li>200 g de frango moído</li><li>1/2 abobrinha pequena ralada e levemente espremida</li><li>2 colheres (sopa) de aveia em flocos finos</li><li>1 colher (sopa) de cebola bem picada</li></ul><h2>Modo de preparo</h2><ol><li>Preaqueça o forno a 200 °C.</li><li>Misture o frango moído, a abobrinha, a aveia e a cebola até obter uma massa úmida que consiga manter o formato.</li><li>Modele porções pequenas com as mãos, sem apertar demais, e disponha em assadeira.</li><li>Asse até o frango estar completamente cozido no centro. Abra uma unidade para conferir o cozimento antes de servir.</li><li>Espere amornar e ajuste o formato conforme as habilidades da criança.</li></ol><h2>Como deve ficar a textura</h2><p>Por dentro, a almôndega deve permanecer macia e úmida, sem centro cru e sem formar uma casca rígida. A textura pode ser conferida pressionando uma unidade pronta com o garfo: ela deve ceder com facilidade.</p><h2>Como servir e adaptar</h2><p>O formato não precisa ser igual para todas as crianças. Sirva de maneira compatível com as habilidades já desenvolvidas, ajustando o tamanho ou desmanchando a preparação com o garfo quando necessário. O Ministério da Saúde recomenda que a consistência dos alimentos evolua gradualmente durante a alimentação complementar.</p><h2>Substituições culinárias</h2><p>A aveia em flocos finos pode ser ajustada em pequena quantidade caso a abobrinha deixe a mistura muito úmida. Outra hortaliça ralada que cozinhe completamente pode ser usada como variação culinária, observando que isso altera textura e umidade. Em caso de alergia ou necessidade alimentar específica, procure profissional habilitado.</p><h2>Armazenamento</h2><p>Prepare com utensílios limpos, mantenha o frango refrigerado antes do preparo e cozinhe completamente. Não guarde novamente a porção que já teve contato com a boca ou com utensílio usado durante a refeição da criança. Para conservação posterior, siga as orientações oficiais de segurança alimentar adequadas à sua refrigeração.</p><h2>Perguntas frequentes</h2><h3>Precisa colocar ovo?</h3><p>Não nesta versão. A aveia e a própria umidade da abobrinha ajudam a unir a mistura. Se a massa estiver muito mole, acrescente aveia aos poucos, apenas até conseguir modelar.</p><h3>Posso fazer com peito de frango?</h3><p>Sim, desde que esteja moído e seja completamente cozido. Evite assar além do necessário para não ressecar a preparação.</p><h3>Como saber se ficou macia?</h3><p>Depois de assada e morna, pressione uma unidade com o garfo. Ela deve se romper com facilidade, sem partes duras, e o centro precisa estar completamente cozido.</p><h2>Receitas relacionadas</h2><ul><li><a href='https://www.receitasparapequenos.site/2026/08/arroz-cremoso-com-frango-e-legumes-para.html'>Arroz Cremoso com Frango e Legumes para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/bolinho-de-batata-doce-e-frango-assado.html'>Bolinho de Batata-Doce e Frango Assado para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/almondegas-de-carne-moida-com-legumes.html'>Almôndegas de Carne Moída com Legumes para Bebês</a></li></ul><h2>Referências oficiais</h2><ul><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/primeira-infancia/alimentacao-saudavel' rel='nofollow'>Ministério da Saúde — Alimentação saudável na primeira infância</a></li><li><a href='https://www.gov.br/saude/pt-br/composicao/saps/promocao-da-saude/guias-alimentares/publicacoes/guia_da_crianca_2019.pdf/view' rel='nofollow'>Ministério da Saúde — Guia Alimentar para Crianças Brasileiras Menores de 2 Anos</a></li></ul><h2>Conclusão</h2><p>Com poucos ingredientes e uma textura que pode ser adaptada, a almôndega de frango com abobrinha é uma forma diferente de usar frango no mesmo cluster de refeições sem repetir a proposta do arroz cremoso.</p><script type='application/ld+json'>{sj}</script>"""
def main():
 tok=base['token'](); posts=base['list_posts'](tok)
 for p in posts:
  t=(p.get('title') or '').casefold()
  if t==TITLE.casefold() or ('almôndega' in t and 'frango' in t and 'abobrinha' in t):
   RESULT_PATH.write_text(f'outcome=skipped_duplicate\ntitle={p.get("title","")}\nurl={p.get("url","")}\n',encoding='utf-8'); base['git_commit_push']([RESULT_PATH],'Record duplicate prevention for chicken zucchini meatballs'); return
 suffix=hashlib.sha1(TITLE.encode()).hexdigest()[:10]; cp=COVER_DIR/f'{SLUG_KEY}-{suffix}.jpg'; cu=f'{RAW_BASE}/{cp.name}'
 if not cp.exists():
  original=base['TITLE']; base['TITLE']=TITLE
  try: base['generate_cover'](cp)
  finally: base['TITLE']=original
  base['git_commit_push']([cp],'Add unique AI food photo for chicken zucchini meatballs'); time.sleep(8)
 content=article(cu)
